import { createHmac, timingSafeEqual } from "node:crypto";

export interface TokenClaims {
  sub: string;
  exp: number;
}

// Verify an HS256 JWT against `secret` and return its claims, or throw.
export function verifyToken(token: string, secret: string): TokenClaims {
  const parts = token.split(".");
  if (parts.length !== 3) throw new Error("malformed token");
  const [headerB64, payloadB64, signatureB64] = parts;

  let header: unknown;
  let payload: unknown;
  try {
    header = JSON.parse(Buffer.from(headerB64, "base64url").toString("utf8"));
    payload = JSON.parse(Buffer.from(payloadB64, "base64url").toString("utf8"));
  } catch {
    throw new Error("malformed token");
  }

  // Pin the algorithm: never trust the header to pick it (rejects "none" and alg confusion).
  if (typeof header !== "object" || header === null || (header as { alg?: unknown }).alg !== "HS256") {
    throw new Error("unsupported algorithm");
  }

  const expected = createHmac("sha256", secret).update(`${headerB64}.${payloadB64}`).digest();
  const actual = Buffer.from(signatureB64, "base64url");
  if (actual.length !== expected.length || !timingSafeEqual(actual, expected)) {
    throw new Error("invalid signature");
  }

  const claims = payload as Partial<TokenClaims>;
  if (typeof claims !== "object" || claims === null || typeof claims.sub !== "string" || typeof claims.exp !== "number") {
    throw new Error("invalid claims");
  }
  if (claims.exp <= Math.floor(Date.now() / 1000)) throw new Error("token expired");

  return { sub: claims.sub, exp: claims.exp };
}

