test("alg none", () => expect(() => verifyToken(`${b({ alg: "none" })}.${b({ sub: "u", exp: now + 60 })}.`, "k")).toThrow("algorithm"));
test("garbage", () => expect(() => verifyToken("a.b", "k")).toThrow("malformed"));

